INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (124, '8JT3', 'lemma', 'Derivatives of the Laplace integral', 'Let $\psi$ be a primitive character and $g(u) = \mathcal G_\psi(e^u)$. For every $k \ge 0$ and every $s \in \C$ with $\Re s > 2$,
\[ \mathcal H_\psi^{(k)}(s) = (-1)^k \int_0^\infty g(u)\, u^k e^{-su}\,du. \]', NULL, 104, 12, 'published', 0, 1, '2026-11-24 19:05:00', '2026-11-24 19:05:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '124', 1, 'hide-differentiation-2026-11-24', '{"tag":"8JT3","type":"lemma","title":"Derivatives of the Laplace integral","statement_tex":"Let $\\psi$ be a primitive character and $g(u) = \\mathcal G_\\psi(e^u)$. For every $k \\ge 0$ and every $s \\in \\C$ with $\\Re s > 2$,\n\\[ \\mathcal H_\\psi^{(k)}(s) = (-1)^k \\int_0^\\infty g(u)\\, u^k e^{-su}\\,du. \\]","section_id":104,"position":12,"listed":0,"aliases":["laplace-derivatives"]}', 'claude');
