INSERT INTO proofs (id, result_id, position, body_tex, body_html_cache, status, generated_by, generator_detail, reviewed_by, review_notes, created_at, updated_at, created_by, updated_by) VALUES (110, 124, 1, '\emph{(1)} \textbf{The derivative may be taken under the integral sign.} By \ref{8JS3}, $|g(u)| \le C_\psi e^{2u}$. Hence for $\Re s \ge \sigma_1 > 2$,
\[ \bigl|g(u)\, u^k e^{-su}\bigr| \le C_\psi\, u^k e^{-(\sigma_1 - 2)u}, \]
which is integrable in $u$ and independent of $s$, so dominated convergence applies.

\emph{(2)} \textbf{Each derivative brings down a factor $-u$ from $e^{-su}$.} Starting from $\mathcal H_\psi(s) = \int_0^\infty g(u)\, e^{-su}\,du$,
\begin{align*}
\mathcal H_\psi''(s) &= -\int_0^\infty g(u)\, u\, e^{-su}\,du, \\
\mathcal H_\psi''''(s) &= \int_0^\infty g(u)\, u^2 e^{-su}\,du, \\
\mathcal H_\psi''''''(s) &= -\int_0^\infty g(u)\, u^3 e^{-su}\,du,
\end{align*}
and in general the $k$-th derivative carries $(-u)^k$.', NULL, 'ai_generated', 'claude', 'claude-opus-5-5', NULL, NULL, '2026-11-24 19:05:00', '2026-11-24 19:05:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '110', 1, 'hide-differentiation-2026-11-24', '{"result_id":124,"body_tex":"\\emph{(1)} \\textbf{The derivative may be taken under the integral sign.} By \\ref{8JS3}, $|g(u)| \\le C_\\psi e^{2u}$. Hence for $\\Re s \\ge \\sigma_1 > 2$,\n\\[ \\bigl|g(u)\\, u^k e^{-su}\\bigr| \\le C_\\psi\\, u^k e^{-(\\sigma_1 - 2)u}, \\]\nwhich is integrable in $u$ and independent of $s$, so dominated convergence applies.\n\n\\emph{(2)} \\textbf{Each derivative brings down a factor $-u$ from $e^{-su}$.} Starting from $\\mathcal H_\\psi(s) = \\int_0^\\infty g(u)\\, e^{-su}\\,du$,\n\\begin{align*}\n\\mathcal H_\\psi''(s) &= -\\int_0^\\infty g(u)\\, u\\, e^{-su}\\,du, \\\\\n\\mathcal H_\\psi''''(s) &= \\int_0^\\infty g(u)\\, u^2 e^{-su}\\,du, \\\\\n\\mathcal H_\\psi''''''(s) &= -\\int_0^\\infty g(u)\\, u^3 e^{-su}\\,du,\n\\end{align*}\nand in general the $k$-th derivative carries $(-u)^k$.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
INSERT INTO refs (source_result_id, source_proof_id, target_tag) VALUES (124, 110, '8JS3');
UPDATE proofs SET body_tex = '\emph{(1)} \textbf{$A_k$ is an average of $g$ against a positive kernel.} Put $g(u) = \mathcal G_\psi(e^u)$, a real function. Substituting $x = e^u$ gives $\mathcal H_\psi(s) = \int_0^\infty g(u)\, e^{-su}\,du$, and \hyperref[8JT3]{differentiating $k$ times under the integral} gives
\[ A_k(\sigma + i\tau) = \int_0^\infty g(u)\, K_k(u)\, e^{-i\tau u}\,du, \qquad K_k(u) = \frac{u^k e^{-\sigma u}}{k!} \ge 0. \]

\emph{(2)} \textbf{Because the kernel is positive, only an upper bound for $g$ is needed.} As $|e^{-i\tau u}| = 1$ and $|g| + g = 2g_+$ with $g_+ = \max(g, 0)$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le \int_0^\infty (|g| + g)\, K_k = 2\int_0^\infty g_+ K_k. \]

\emph{(3)} \textbf{The kernel is a sharp peak at $u = k/\sigma$, and multiplying it by $e^{au}$ just replaces $\sigma$ by $\sigma - a$.} For $a < \sigma$,
\[ e^{au} K_k(u) = (\sigma - a)^{-k-1}\, p_{\sigma - a}(u), \qquad p_\beta(u) = \frac{\beta^{k+1} u^k e^{-\beta u}}{k!}, \]
where $p_\beta$ is the density of the Gamma distribution with shape $k+1$ and rate $\beta$, with mean $(k+1)/\beta$. In particular $\int_0^\infty e^{au} K_k = (\sigma - a)^{-k-1}$, and by Chernoff''s bound, for $0 < \eta < 1$,
\[ \int_{|u - (k+1)/\beta| > \eta (k+1)/\beta} p_\beta(u)\,du \le 2 e^{-c(\eta)\, k}, \qquad c(\eta) = \eta - \log(1+\eta) > 0. \]
Panel (a) shows $K_1, K_2, K_3$; panel (b) shows how the peak narrows, relative to its position, as $k$ grows.
\includegraphics[width=1, alt=The kernel K_k for k = 1, 2, 3, and rescaled kernels for k = 3, 30, 300 aimed at the window from U to 3U/2]{/static/figures/gamma-kernel.svg}

\emph{(4)} \textbf{Choose $k$ so that the peak sits in the middle of the window where the hypothesis holds.} With $x = e^u$ and $U = \log Y$, the window $Y \le x \le Y^{3/2}$ becomes $W = [U, \frac32 U]$, whose midpoint is $\frac54 U$. So take
\[ k = \bigl\lceil \tfrac54 \sigma U \bigr\rceil, \qquad \text{so that } k/\sigma \approx \tfrac54 U. \]
On $W$ we have $g_+(u) \le e^{\theta u}$, so by (3) with $a = \theta$, the window contributes at most $\int_0^\infty e^{\theta u} K_k = (\sigma - \theta)^{-k-1}$.

\emph{(5)} \textbf{Outside the window the crude growth of $g$ only moves the peak slightly, which is harmless once $\sigma$ is large.} Off $W$ we only know $g_+ \le C_\psi e^{2u}$, so we use (3) with $a = 2$: the peak moves to $m = (k+1)/(\sigma - 2)$ and the mass becomes $(\sigma - 2)^{-k-1}$. Fix $\eta > 0$ with $\frac54 (1+\eta)^2 < \frac32$, and $\sigma_0 > 2$ with
\[ \frac{\sigma_0}{\sigma_0 - 2} < \min\bigl(1 + \eta,\ e^{c(\eta)}\bigr); \]
this then holds for every $\sigma \ge \sigma_0$ in place of $\sigma_0$. Then $\frac54 U \le m \le \frac54 (1+\eta) U + o(U)$, so $[(1-\eta)m, (1+\eta)m] \subset W$ for large $U$, and
\[ \int_{u \notin W} g_+ K_k \le 2 C_\psi\, (\sigma - 2)^{-k-1} e^{-c(\eta) k} \le 2 C_\psi\, (\sigma - \theta)^{-k}, \]
since $(\sigma - \theta)/(\sigma - 2) < \sigma/(\sigma - 2) < e^{c(\eta)}$.

\emph{(6)} \textbf{Every $Y$ from the hypothesis gives one good $k$, so there are infinitely many.} Let $K$ be the set of $k = \lceil \frac54 \sigma \log Y \rceil$ for the $Y$ given by the hypothesis that are large enough for (5); it is infinite because these $Y$ are unbounded. For $k \in K$ and $\tau \in \R$, (2), (4) and (5) give the claim with $C = 2 + 4 C_\psi$.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 19:05:00', updated_by = 'claude' WHERE id = 109;
